@startuml

class Scene {
  + code : string
  + description : string
}

class Setup {
  + code : string
  + photographicParameters : string
}

class Take {
  + takeNumber : int
  + filmLength : float
  + reelCode : string
}

class InternalScene extends Scene {}

class ExternalScene extends Scene {}

class DayScene extends ExternalScene {}

class NightScene extends ExternalScene {}

class Location {
  + code : string
  + address : string
  + description : string
}

Scene "1" *-- "1..*" Setup
Setup "1" *-- "1..*" Take
ExternalScene "0..*" -- "1" Location

@enduml

